#!/usr/bin/env python3
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1]
refs=json.loads((ROOT/'docs/REFERENCIAS_STORYLOOP.json').read_text())['references']
head='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VJ Generative — prévias dos motores</title><style>body{margin:0;background:#101017;color:#eeeef5;font:15px system-ui,sans-serif}header{padding:30px;max-width:1500px;margin:auto}h1{font-size:28px;margin:0 0 10px}p{color:#aaaabb;line-height:1.5}input{font:inherit;width:min(600px,90%);padding:13px;background:#1c1c28;color:white;border:1px solid #3e3e52;border-radius:8px}main{max-width:1500px;margin:auto;padding:0 24px 40px;display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:20px}article{background:#191923;border:1px solid #29293a;border-radius:10px;overflow:hidden}video{width:100%;aspect-ratio:16/9;background:black}h2{font-size:16px;margin:14px}a{color:#a9d1ff}small{display:block;color:#aaaabd;margin:14px}.approved{color:#8de4ad}article[hidden]{display:none}</style><header><h1>VJ GENERATIVE · V1.7</h1><p>82 motores no plugin · 75 prévias da expansão. Imagens e vídeos renderizados pelos próprios shaders. Spotlight 1 e Flow Dark Glass aprovados pelo operador; os demais aguardam avaliação visual no Resolume.</p><input type="search" id="search" placeholder="Buscar motor pelo nome" aria-label="Buscar motor"><p>Abra um vídeo para avaliar o movimento. As prévias têm 12 segundos; a DLL renderiza no tamanho de saída configurado.</p></header><main>'''
cards=[]
for r in refs:
 eid=r['engine_id'];name=html.escape(r['name']);status='<span class="approved">Aprovado pelo operador</span>' if eid in [13,19] else ('Vitral corrigido — avaliar' if eid==20 else 'Avaliação visual pendente')
 cards.append(f'<article data-name="{name.lower()}"><video controls loop muted playsinline preload="none" poster="{eid:02d}_05.png"><source src="{eid:02d}_preview.mp4" type="video/mp4"></video><h2>{eid:02d} · {name}</h2><small>{status}</small><small><a href="{html.escape(r["url"])}" target="_blank" rel="noopener">Referência enviada</a></small></article>')
tail='''</main><script>const s=document.getElementById('search');s.addEventListener('input',()=>{const q=s.value.toLocaleLowerCase('pt-BR');document.querySelectorAll('article').forEach(a=>a.hidden=!a.dataset.name.includes(q))});document.addEventListener('play',e=>{if(e.target.tagName==='VIDEO')document.querySelectorAll('video').forEach(v=>{if(v!==e.target)v.pause()})},true)</script></html>'''
(ROOT/'previews/v17/index.html').write_text(head+'\n'.join(cards)+tail)
